144	func TestRiskQuoteTriggerCancelsBuysDescending(t *testing.T) {
145		e := setupHolding(t, 10) // cash 900, pos A 10, quote A seq1@10
146		mustSetMax(t, e, "B", 100)
147		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 1, Price: 20}, 1)
148		bID := mustBuy(t, e, "B", 5, 20) // id=2，占用 100，未成交
149	
150		if err := e.StartTradingDay(1, 90); err != nil {
151			t.Fatal(err)
152		}
153		if st := e.RiskStatus(); st.Baseline != 1000 {
154			t.Fatalf("基准应为 900 现金 + 100 市值 = 1000: %+v", st)
155		}
156	
157		// 先盈后亏均不触线。
158		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 11}, 1)
159		if st := e.RiskStatus(); st.Loss != 0 {
160			t.Fatalf("浮盈时亏损应记零: %+v", st)
161		}
162		aID := mustBuy(t, e, "A", 3, 9) // id=3，占用 27
163	
164		// 跌到 2：净值 920，亏损 80，未触线。
165		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 2}, 1)
166		if e.RiskStatus().Restricted {
167			t.Fatal("亏损 80 未达上限 90，不应触线")
168		}
169	
170		// 跌到 1：净值 910，亏损 90，达到上限，触线。
171		mustQuote(t, e, "A", Quote{Seq: 4, Moment: 4, Price: 1}, 1)
172		st2 := e.RiskStatus()
173		if !st2.Restricted || st2.Equity != 910 || st2.Loss != 90 {
174			t.Fatalf("亏损达到上限应触线: %+v", st2)
175		}
176	
177		// 触线记录内容。
178		rec := lastRiskRecord(t, e)
179		if rec.RiskTrigger != RiskTriggerQuote || rec.RiskRefSeq != 4 || rec.RiskRefMoment != 4 {
180			t.Fatalf("触线记录来源/关联报价错误: trigger=%s ref=%d moment=%d",
181				rec.RiskTrigger, rec.RiskRefSeq, rec.RiskRefMoment)
182		}
183		if rec.RiskDay != 1 || rec.RiskBaseline != 1000 || rec.RiskEquity != 910 ||
184			rec.RiskLoss != 90 || rec.RiskLimit != 90 || !rec.RiskRestrict {
185			t.Fatalf("触线记录风险快照错误: %+v", rec)
186		}
187		if len(rec.RiskQuoteRefs) != 1 {
188			t.Fatalf("应保存 A 一个持仓合约的报价，实际 %+v", rec.RiskQuoteRefs)
189		}
190		ref := rec.RiskQuoteRefs[0]
191		if ref.Symbol != "A" || ref.Seq != 4 || ref.Moment != 4 || ref.Price != 1 {
192			t.Fatalf("持仓报价定位错误: %+v", ref)
193		}
194	
195		// 撤销顺序：编号从大到小（id=3 的 A 买单先，id=2 的 B 买单后），全部跨合约撤销。
196		var canceledIDs []int64
197		var sawTrigger bool
198		for _, r := range e.Records() {
199			if r.Kind == RecordRiskTriggered {
200				sawTrigger = true
201				continue
202			}
203			if sawTrigger && r.Kind == RecordCanceled {
204				canceledIDs = append(canceledIDs, r.OrderID)
205				if r.RiskDay != 1 || r.RiskLoss != 90 || r.RiskLimit != 90 || !r.RiskRestrict {
206					t.Fatalf("触线撤单记录必须携带当日亏损与上限: %+v", r)
207				}
208			}
209		}
210		if len(canceledIDs) != 2 || canceledIDs[0] != aID || canceledIDs[1] != bID {
211			t.Fatalf("应按编号降序撤销 %d,%d，实际 %v", aID, bID, canceledIDs)
212		}
213		if e.ReservedCash() != 0 {
214			t.Fatalf("撤单应释放全部买单占用: reserved=%d", e.ReservedCash())
215		}
216		if e.Cash() != 900 || e.Position("A") != 10 {
217			t.Fatalf("已入账成交、现金与持仓必须保留: cash=%d pos=%d", e.Cash(), e.Position("A"))
218		}
219		for _, o := range e.Orders() {
220			if o.Status == StatusCanceled {
221				continue
222			}
223			if o.Side == Buy && o.Remaining() > 0 {
224				t.Fatalf("不得残留有效买单: %+v", o)
225			}
226		}
227	
228		// 所有合约新买单被拒，拒绝记录携带当日亏损与上限。
229		recsBefore := len(e.Records())
230		if _, err := e.Buy("B", 1, 1); err == nil {
231			t.Fatal("触线后 B 合约买单也必须拒绝")
232		}
233		rj := e.Records()[recsBefore]
234		if rj.Kind != RecordRejected || rj.RiskLoss != 90 || rj.RiskLimit != 90 ||
235			!rj.RiskRestrict || rj.RiskDay != 1 {
236			t.Fatalf("触线拒单记录风险快照错误: %+v", rj)
237		}
238	
239		// 卖单、卖单成交、主动撤卖单仍按原规则处理。
240		sid := mustSell(t, e, "A", 5, 1)
241		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 1, Qty: 5}); err != nil {
242			t.Fatal(err)
243		}
244		if e.Cash() != 905 || e.Position("A") != 5 {
245			t.Fatalf("触线后卖出成交应正常入账: cash=%d pos=%d", e.Cash(), e.Position("A"))
246		}
247		sid2 := mustSell(t, e, "A", 2, 1)
248		if err := e.Cancel(sid2); err != nil {
249			t.Fatalf("触线后主动撤卖单应正常: %v", err)
250		}
251	
252		// 报价回升不解除限制。
253		mustQuote(t, e, "A", Quote{Seq: 5, Moment: 5, Price: 100}, 1)
254		if !e.RiskStatus().Restricted {
255			t.Fatal("报价回升不得解除限制")
256		}
257		// 调高上限也不解除。
258		if err := e.SetLossLimit(math.MaxInt64); err != nil {
259			t.Fatal(err)
260		}
261		if !e.RiskStatus().Restricted {
262			t.Fatal("调高上限不得解除限制")
263		}
264		if countRiskRecords(e) != 1 {
265			t.Fatal("一个交易日只能有一条触线记录")
266		}
267	}
