445		if len(rec.RiskQuoteRefs) != 2 {
446			t.Fatalf("触线记录必须保存各持仓合约报价: %+v", rec.RiskQuoteRefs)
447		}
448		// 按合约排序、序号/时刻/价格俱全。
449		if rec.RiskQuoteRefs[0] != (RiskQuoteRef{Symbol: "A", Seq: 2, Moment: 9, Price: 1}) {
450			t.Fatalf("A 报价定位错误: %+v", rec.RiskQuoteRefs[0])
451		}
452		if rec.RiskQuoteRefs[1] != (RiskQuoteRef{Symbol: "B", Seq: 1, Moment: 1, Price: 20}) {
453			t.Fatalf("B 报价定位错误: %+v", rec.RiskQuoteRefs[1])
454		}
455	}
