590	func TestRiskRecordsAreImmutableAcrossChanges(t *testing.T) {
591		e := setupHolding(t, 10) // cash 900, pos A 10
592		if err := e.StartTradingDay(1, 90); err != nil {
593			t.Fatal(err)
