616		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 100}, 1)
617		if err := e.StartTradingDay(2, 100); err != nil {
618			t.Fatal(err)
619		}
620		again = lastRiskRecord(t, e)
621		if again.RiskDay != 1 || again.RiskLoss != 90 || again.RiskLimit != 90 ||
622			again.RiskQuoteRefs[0].Price != 1 {
