120		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 20, Price: 11}, 0)
121	
122		// 重复序号内容不同：报错且保留原值。
123		if _, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 99, Price: 11}); err == nil {
124			t.Fatal("重复序号不同时刻必须报错")
