333	func TestFillIdempotency(t *testing.T) {
334		e, _ := NewEngine(1000)
335		mustSetMax(t, e, "A", 100)
336		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
337		id := mustBuy(t, e, "A", 10, 10)
338	
339		tr := Trade{TradeID: 77, OrderID: id, Symbol: "A", Side: Buy, Price: 9, Qty: 4}
340		res1, err := e.Fill(tr)
341		if err != nil {
342			t.Fatal(err)
343		}
344		recordsBefore := len(e.Records())
345	
346		// 相同编号相同内容：返回原结果，不新增事件，不再次记账。
347		res2, err := e.Fill(tr)
348		if err != nil {
349			t.Fatal(err)
350		}
351		if res1 != res2 {
352			t.Fatalf("幂等结果不一致: %+v vs %+v", res1, res2)
353		}
354		if len(e.Records()) != recordsBefore {
355			t.Fatal("幂等成交不得新增事件记录")
356		}
357		if e.Cash() != 1000-36 || e.Position("A") != 4 || e.ReservedCash() != 60 {
358			t.Fatalf("幂等重放不得再次记账: cash=%d pos=%d reserved=%d", e.Cash(), e.Position("A"), e.ReservedCash())
359		}
360	
361		// 撤销订单后，旧编号重放仍返回原结果，不能再次记账。
362		if err := e.Cancel(id); err != nil {
363			t.Fatal(err)
364		}
365		res3, err := e.Fill(tr)
366		if err != nil {
367			t.Fatal(err)
368		}
369		if res3 != res1 {
370			t.Fatalf("撤单后幂等结果应保持: %+v vs %+v", res3, res1)
371		}
372		if e.Cash() != 1000-36 || e.Position("A") != 4 {
373			t.Fatalf("撤单后重放旧成交不得记账: cash=%d pos=%d", e.Cash(), e.Position("A"))
374		}
375	
376		// 同一编号不同内容：报错且不改状态。记录条数会增加一条拒绝。
377		before := len(e.Records())
378		if _, err := e.Fill(Trade{TradeID: 77, OrderID: id, Symbol: "A", Side: Buy, Price: 8, Qty: 4}); err == nil {
379			t.Fatal("同一编号不同内容必须报错")
380		}
381		if len(e.Records()) != before+1 {
382			t.Fatal("编号冲突拒绝应记录一条拒绝")
383		}
384	
385		// 被拒绝的成交不占用编号：新订单修正后仍可用新编号提交。
386		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 1, Price: 5}, 1)
387		mustSetMax(t, e, "B", 100)
388		b2 := mustBuy(t, e, "B", 10, 5)
389		// 先用编号 88 提交一笔会被拒绝的成交（超量）。
390		if _, err := e.Fill(Trade{TradeID: 88, OrderID: b2, Symbol: "B", Side: Buy, Price: 5, Qty: 99}); err == nil {
391			t.Fatal("超量成交应拒绝")
392		}
393		// 编号 88 未被占用，修正数量后提交成功。
394		if _, err := e.Fill(Trade{TradeID: 88, OrderID: b2, Symbol: "B", Side: Buy, Price: 5, Qty: 2}); err != nil {
395			t.Fatalf("被拒绝编号应可复用: %v", err)
396		}
397	}
